from itertools import product

def valid(s):
  s = [' '] + list(s) + [' ']
  for i in range(1,len(s)-1):
     if s[i] == 'A' and s[i-1] != 'D' and s[i+1] != 'D':
        return False
     if s[i] == 'C' and ((s[i-1] == 'B') or (s[i+1] == 'B')):
        return False
  return True

candidates = product('ABCD', repeat=3)

v = [s for s in candidates if valid(s)]

print( len(v) )

A = "ЖАЛЕЙ"
N = 5
no = [ ".Й", "ЕЙ", "ЙЕ", "Й." ]

def valid( word ):
  word = '.' + word + '.'
  if word.count("Й") > 1:
    return False
  for ex in no:
    if ex in word:
      return False
  return True

def rec( word, k, Alpha ):
  if len(word) == k:
    if valid(word): return 1
    return 0
  count = 0
  for c in Alpha:
    count += rec( word+c, k, Alpha )
  return count

print( rec( "", N, A ) )

