from itertools import product

def valid( s ):
  if s[0] == 0: return False
  res = False
  for k in [2,3]:
    if s[0] % k == 0:
      res, d = True, k
      for i in range(1,5):
        d = 5 - d
        res = res and s[i] % d == 0
    if res: break
  return res

count = 0
for s in product(range(15), repeat=5):
   if valid(s):
      count += 1

print( count )

def base4( n ):
  s = ''
  while n:
    s = str(n%4) + s
    n //= 4
  return s

count = 0
for i in range(4**3, 4**4):
  s = base4(i)
  if any( s.count(c) >= 2 for c in '0123' ) :
     count += 1

print( count )

